        "script.js": "// Workshop 2: ทำให้หน้า Electrical Meter โต้ตอบได้\n// HTML และ CSS เตรียมไว้ให้แล้ว เขียนเฉพาะไฟล์นี้ ห้ามเปลี่ยน id ใน index.html\n\nconst MAX_VOLTAGE = 240;\nconst $ = (id) => document.getElementById(id);   // ย่อ document.getElementById ให้สั้นลง\n\n// ---------------------------------------------------------- Workshop 2.1: Start / Stop\n// TODO 1: เขียนฟังก์ชัน setStatus(isRunning)\n//   - true  → #status แสดง 'RUNNING' และ className = 'badge run'  (เขียว)\n//   - false → #status แสดง 'STOP'    และ className = 'badge stop' (แดง)\nfunction setStatus(isRunning) {\n\n}\n\n// TODO 2: ผูก Event 'click'\n//   - #start-btn เรียก setStatus(true)\n//   - #stop-btn  เรียก setStatus(false)\n\n\n// ---------------------------------------------------------- Workshop 2.2: Simple Meter\n// TODO 3: เขียนฟังก์ชัน checkVoltage(v)\n//   - v มากกว่า MAX_VOLTAGE → คืนข้อความ 'Warning: แรงดันเกิน 240 V'\n//   - ไม่เกิน → คืนข้อความว่าง ''\nfunction checkVoltage(v) {\n\n}\n\n// TODO 4: ผูก Event 'input' ที่ #volt-input\n//   - อ่านค่าจาก event.target.value (เป็น String) แปลงด้วย Number()\n//   - ถ้าช่องว่าง ให้ล้าง #warning\n//   - ไม่อย่างนั้นแสดงผลของ checkVoltage ใน #warning\n",
        "style.css": "/* สไตล์จาก Workshop 1 */\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 24px;\n  font-family: Tahoma, sans-serif;\n  background: #111827;\n  color: #e5e7eb;\n}\n\nheader { text-align: center; margin-bottom: 24px; }\nh1 { margin: 0; }\n.sub { margin: 4px 0 0; color: #9ca3af; }\n\n.cards {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 16px;\n}\n\n.card {\n  flex: 1 1 240px;\n  max-width: 420px;\n  padding: 20px;\n  border-radius: 10px;\n  background: #0b1220;\n  text-align: center;\n}\n\n.label { margin: 0; font-weight: bold; }\n.value { margin: 12px 0 0; font-size: 40px; font-weight: bold; }\n.unit { font-size: 16px; color: #9ca3af; }\n.voltage { color: #38bdf8; }\n.current { color: #22c55e; }\n.water { color: #a78bfa; }\n\n/* ส่วนควบคุมเครื่อง (เตรียมไว้ให้แล้วใน Workshop 2 ไม่ต้องแก้) */\n.panel {\n  max-width: 860px;\n  margin: 24px auto 0;\n  padding: 20px;\n  border-radius: 10px;\n  background: #0b1220;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 12px 24px;\n}\n\n.status-row { display: flex; align-items: center; gap: 12px; }\n\n/* มาตรฐานสี Industrial UI: เขียว ทำงาน / แดง หยุด / เทา ยังไม่เริ่ม */\n.badge {\n  display: inline-block;\n  min-width: 110px;\n  padding: 6px 16px;\n  border-radius: 6px;\n  background: #6b7280;\n  color: #ffffff;\n  font-weight: bold;\n  text-align: center;\n}\n.badge.run { background: #22c55e; color: #052e16; }\n.badge.stop { background: #ef4444; }\n\n.buttons { display: flex; gap: 8px; }\n\nbutton {\n  min-width: 44px;\n  min-height: 44px;\n  padding: 8px 20px;\n  border: 0;\n  border-radius: 8px;\n  font: inherit;\n  font-weight: bold;\n  cursor: pointer;\n}\n#start-btn { background: #22c55e; color: #052e16; }\n#stop-btn { background: #ef4444; color: #ffffff; }\nbutton:disabled { opacity: 0.5; cursor: not-allowed; }\n\n.meter-input { display: flex; align-items: center; gap: 8px; }\n.meter-input input {\n  width: 110px;\n  min-height: 44px;\n  padding: 6px 10px;\n  border: 1px solid #374151;\n  border-radius: 6px;\n  background: #111827;\n  color: #e5e7eb;\n  font: inherit;\n}\n\n.warning { flex-basis: 100%; margin: 0; min-height: 1.5em; color: #f87171; font-weight: bold; }\n\n.note { text-align: center; color: #9ca3af; font-size: 14px; margin: 16px 0 0; }\n.note.error { color: #f87171; }\n"
