      "solutionFiles": {
        "index.html": "<!DOCTYPE html>\n<html lang=\"th\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Electrical Meter</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header>\n    <h1>Electrical Meter</h1>\n    <p class=\"sub\">Real-time Voltage &amp; Current</p>\n  </header>\n\n  <main>\n    <section class=\"cards\">\n      <article class=\"card\">\n        <p class=\"label\">Voltage</p>\n        <p class=\"value voltage\"><span id=\"voltage\">230</span> <span class=\"unit\">V</span></p>\n      </article>\n      <article class=\"card\">\n        <p class=\"label\">Current</p>\n        <p class=\"value current\"><span id=\"current\">15.8</span> <span class=\"unit\">A</span></p>\n      </article>\n      <!-- Workshop 3 -->\n      <article class=\"card\">\n        <p class=\"label\">Water Flow</p>\n        <p class=\"value water\"><span id=\"water\">–</span> <span class=\"unit\">m³/h</span></p>\n      </article>\n    </section>\n\n    <!-- Workshop 2 -->\n    <section class=\"panel\">\n      <div class=\"status-row\">\n        <span class=\"label\">Machine</span>\n        <span id=\"status\" class=\"badge\">IDLE</span>\n      </div>\n      <div class=\"buttons\">\n        <button id=\"start-btn\" type=\"button\">Start</button>\n        <button id=\"stop-btn\" type=\"button\">Stop</button>\n      </div>\n      <div class=\"meter-input\">\n        <label for=\"volt-input\">ทดสอบแรงดัน (V)</label>\n        <input id=\"volt-input\" type=\"number\" inputmode=\"decimal\" placeholder=\"เช่น 245\">\n      </div>\n      <p id=\"warning\" class=\"warning\"></p>\n    </section>\n\n    <!-- Workshop 3 -->\n    <p id=\"updated\" class=\"note\">ยังไม่ได้โหลดข้อมูล</p>\n  </main>\n\n  <script src=\"script.js\" defer></script>\n</body>\n</html>\n",
        "script.js": "// เฉลย Workshop 3 (รวมงานจาก Workshop 2)\n\nconst API_URL = 'data/meter.json';  // หรือ API สำรองของผู้สอน เช่น http://192.168.1.10:8000/api/meter\nconst MAX_VOLTAGE = 240;\nconst REFRESH_MS = 5000;\n\nconst $ = (id) => document.getElementById(id);\n\n// ---------------------------------------------------------- Workshop 2.1: Start / Stop\nfunction setStatus(isRunning) {\n  $('status').textContent = isRunning ? 'RUNNING' : 'STOP';\n  $('status').className = isRunning ? 'badge run' : 'badge stop';\n}\n\n$('start-btn').addEventListener('click', () => setStatus(true));\n$('stop-btn').addEventListener('click', () => setStatus(false));\n\n// ---------------------------------------------------------- Workshop 2.2: Simple Meter\nfunction checkVoltage(v) {\n  return v > MAX_VOLTAGE ? `Warning: แรงดันเกิน ${MAX_VOLTAGE} V` : '';\n}\n\n$('volt-input').addEventListener('input', (event) => {\n  const raw = event.target.value;\n  $('warning').textContent = raw === '' ? '' : checkVoltage(Number(raw));\n});\n\n// ---------------------------------------------------------- Workshop 3: ดึงค่าน้ำ-ไฟจาก API\nasync function loadMeter() {\n  try {\n    const res = await fetch(API_URL, { cache: 'no-store' });\n    if (!res.ok) throw new Error('HTTP ' + res.status);\n    const data = await res.json();\n    $('voltage').textContent = data.electric.voltage.toFixed(1);\n    $('current').textContent = data.electric.current.toFixed(1);\n    $('water').textContent = data.water.flow.toFixed(1);\n    $('warning').textContent = checkVoltage(data.electric.voltage);\n    $('updated').textContent = 'อัปเดตล่าสุด ' + new Date().toLocaleTimeString('th-TH');\n    $('updated').classList.remove('error');\n  } catch (err) {\n    $('updated').textContent = 'โหลดข้อมูลไม่สำเร็จ';   // ค่าเดิมบนการ์ดยังอยู่\n    $('updated').classList.add('error');\n    console.error(err);\n  }\n}\n\nloadMeter();\nsetInterval(loadMeter, REFRESH_MS);\n",
        "style.css": "/* สไตล์จาก Workshop 1 */\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 24px;\n  font-family: Tahoma, sans-serif;\n  background: #111827;\n  color: #e5e7eb;\n}\n\nheader { text-align: center; margin-bottom: 24px; }\nh1 { margin: 0; }\n.sub { margin: 4px 0 0; color: #9ca3af; }\n\n.cards {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 16px;\n}\n\n.card {\n  flex: 1 1 240px;\n  max-width: 420px;\n  padding: 20px;\n  border-radius: 10px;\n  background: #0b1220;\n  text-align: center;\n}\n\n.label { margin: 0; font-weight: bold; }\n.value { margin: 12px 0 0; font-size: 40px; font-weight: bold; }\n.unit { font-size: 16px; color: #9ca3af; }\n.voltage { color: #38bdf8; }\n.current { color: #22c55e; }\n.water { color: #a78bfa; }\n\n/* ส่วนควบคุมเครื่อง (เตรียมไว้ให้แล้วใน Workshop 2 ไม่ต้องแก้) */\n.panel {\n  max-width: 860px;\n  margin: 24px auto 0;\n  padding: 20px;\n  border-radius: 10px;\n  background: #0b1220;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 12px 24px;\n}\n\n.status-row { display: flex; align-items: center; gap: 12px; }\n\n/* มาตรฐานสี Industrial UI: เขียว ทำงาน / แดง หยุด / เทา ยังไม่เริ่ม */\n.badge {\n  display: inline-block;\n  min-width: 110px;\n  padding: 6px 16px;\n  border-radius: 6px;\n  background: #6b7280;\n  color: #ffffff;\n  font-weight: bold;\n  text-align: center;\n}\n.badge.run { background: #22c55e; color: #052e16; }\n.badge.stop { background: #ef4444; }\n\n.buttons { display: flex; gap: 8px; }\n\nbutton {\n  min-width: 44px;\n  min-height: 44px;\n  padding: 8px 20px;\n  border: 0;\n  border-radius: 8px;\n  font: inherit;\n  font-weight: bold;\n  cursor: pointer;\n}\n#start-btn { background: #22c55e; color: #052e16; }\n#stop-btn { background: #ef4444; color: #ffffff; }\nbutton:disabled { opacity: 0.5; cursor: not-allowed; }\n\n.meter-input { display: flex; align-items: center; gap: 8px; }\n.meter-input input {\n  width: 110px;\n  min-height: 44px;\n  padding: 6px 10px;\n  border: 1px solid #374151;\n  border-radius: 6px;\n  background: #111827;\n  color: #e5e7eb;\n  font: inherit;\n}\n\n.warning { flex-basis: 100%; margin: 0; min-height: 1.5em; color: #f87171; font-weight: bold; }\n\n.note { text-align: center; color: #9ca3af; font-size: 14px; margin: 16px 0 0; }\n.note.error { color: #f87171; }\n",
        "data/meter.json": "{\n  \"line\": \"A\",\n  \"electric\": { \"voltage\": 231.4, \"current\": 15.6 },\n  \"water\": { \"flow\": 3.2 },\n  \"updatedAt\": \"2026-11-04T11:05:00+07:00\"\n}\n"
      }
