    "style.css": "/* T1: จัดหน้าจอ Dashboard ที่นี่\n   - การ์ด 4 ใบเรียงเป็นแถวด้วย Flexbox และตัดลงบรรทัดเมื่อจอแคบ\n   - ตัวเลขในการ์ด (.value) ต้องเด่น อ่านได้ภายใน 5 วินาที\n   - สถานะ (#status) ใช้ class ok / warn / bad / off ตามมาตรฐานสี Industrial UI */\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 24px;\n  font-family: \"Leelawadee UI\", Tahoma, sans-serif;\n}\n",
    "data/performance.json": "{\n  \"line\": {\n    \"name\": \"A\",\n    \"shift\": \"Day\"\n  },\n  \"output\": {\n    \"target\": 1200,\n    \"actual\": 1104\n  },\n  \"defect\": 18,\n  \"updatedAt\": \"2026-11-05T10:30:00+07:00\"\n}\n",
    "data/samples/boundary-60.json": "{\n  \"line\": {\n    \"name\": \"A\",\n    \"shift\": \"Day\"\n  },\n  \"output\": {\n    \"target\": 1200,\n    \"actual\": 720\n  },\n  \"defect\": 18,\n  \"updatedAt\": \"2026-11-05T10:30:00+07:00\"\n}\n",
    "data/samples/boundary-85.json": "{\n  \"line\": {\n    \"name\": \"A\",\n    \"shift\": \"Day\"\n  },\n  \"output\": {\n    \"target\": 1200,\n    \"actual\": 1020\n  },\n  \"defect\": 18,\n  \"updatedAt\": \"2026-11-05T10:30:00+07:00\"\n}\n",
