    "data/samples/normal.json": "{\n  \"line\": {\n    \"name\": \"A\",\n    \"shift\": \"Day\"\n  },\n  \"output\": {\n    \"target\": 1200,\n    \"actual\": 1104\n  },\n  \"defect\": 18,\n  \"updatedAt\": \"2026-11-05T10:30:00+07:00\"\n}\n",
    "data/samples/watch.json": "{\n  \"line\": {\n    \"name\": \"A\",\n    \"shift\": \"Day\"\n  },\n  \"output\": {\n    \"target\": 1200,\n    \"actual\": 900\n  },\n  \"defect\": 18,\n  \"updatedAt\": \"2026-11-05T10:30:00+07:00\"\n}\n"
